#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>

using namespace std;

/**
 * Problem: 10604 - Packing Polygons
 * 
 * 解題思路：
 * 1. 題目要求判斷是否存在半徑為 R 的圓包含整個多邊形。
 * 2. 這等同於判斷多邊形的所有頂點是否能被半徑為 R 的圓覆蓋。
 * 3. 即判斷該頂點集的「最小覆蓋圓」半徑是否小於等於 R。
 * 4. 可以使用 Welzl's Algorithm 在 O(n) 時間內求最小覆蓋圓。
 */

struct Point {
    double x, y;
};

double dist(Point a, Point b) {
    return sqrt(pow(a.x - b.x, 2) + pow(a.y - b.y, 2));
}

struct Circle {
    Point center;
    double r;
};

Circle circle_from_2_points(Point a, Point b) {
    return {{(a.x + b.x) / 2.0, (a.y + b.y) / 2.0}, dist(a, b) / 2.0};
}

Circle circle_from_3_points(Point a, Point b, Point c) {
    double a2 = a.x * a.x + a.y * a.y;
    double b2 = b.x * b.x + b.y * b.y;
    double c2 = c.x * c.x + c.y * c.y;
    double d = 2 * (a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y));
    if (abs(d) < 1e-9) return {{0, 0}, 1e18}; // 共線
    double ux = (a2 * (b.y - c.y) + b2 * (c.y - a.y) + c2 * (a.y - b.y)) / d;
    double uy = (a2 * (c.x - b.x) + b2 * (a.x - c.x) + c2 * (b.x - a.x)) / d;
    Point center = {ux, uy};
    return {center, dist(center, a)};
}

int main() {
    int n;
    while (cin >> n && n != 0) {
        vector<Point> p(n);
        for (int i = 0; i < n; ++i) cin >> p[i].x >> p[i].y;
        double R;
        cin >> R;

        // Welzl's Algorithm (簡易版隨機化)
        random_shuffle(p.begin(), p.end());
        Circle c = {p[0], 0};
        for (int i = 1; i < n; ++i) {
            if (dist(c.center, p[i]) > c.r + 1e-9) {
                c = {p[i], 0};
                for (int j = 0; j < i; ++j) {
                    if (dist(c.center, p[j]) > c.r + 1e-9) {
                        c = circle_from_2_points(p[i], p[j]);
                        for (int k = 0; k < j; ++k) {
                            if (dist(c.center, p[k]) > c.r + 1e-9) {
                                c = circle_from_3_points(p[i], p[j], p[k]);
                            }
                        }
                    }
                }
            }
        }

        if (c.r <= R + 1e-9) {
            cout << "The polygon can be packed in the circle." << endl;
        } else {
            cout << "There is no way of packing that polygon." << endl;
        }
    }
    return 0;
}
